DO $ingest$
DECLARE p jsonb := $payload${"ley":{"id":"f7419b4e-49eb-5425-a439-562f25a4d581","titulo":"Acuerdo por el que se emite la modificación a la Segunda Convocatoria para la atención prioritaria de solicitudes de permisos de generación de energía eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante [DOF 26/05/2026]","siglas":"CONV-GEN-2-M1","fecha_publicacion":"2026-05-26","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Segunda convocatoria de generación","Convocatorias","Modificación","Interconexión"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5788509","tipo":"acuerdo"},"articulos":[{"id":"3f2d1f60-26d4-5033-86ed-c33cbca9e79b","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":0,"identificador":"Nota editorial · versiones relacionadas","contenido":"### Nota editorial · versión publicada y documentos relacionados\n\nEste registro reproduce la publicación del DOF de 26/05/2026. Se conserva el texto de esa publicación; las modificaciones se consultan en registros separados. No es un texto consolidado ni una indicación de que todos sus plazos permanezcan abiertos.\n\nDocumentos de la misma convocatoria incorporados al acervo:\n\n- <a href=\"/#ley-2dde9c74-5c23-507b-a0ae-5d3b4722d927\" target=\"_blank\" rel=\"noopener noreferrer\">Texto original · 11/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5787117)\n- <a href=\"/#ley-f7419b4e-49eb-5425-a439-562f25a4d581\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 1 · 26/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5788509)\n- <a href=\"/#ley-bc6128cd-901e-52ff-8283-2ac07b7f633a\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 2 · 08/06/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5789883)\n- <a href=\"/#ley-d026115a-998a-544f-bff0-39f93c04f444\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 3 · 18/06/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5790938)\n- <a href=\"/#ley-8db24d0b-34a8-53dc-8cd3-1498d478e568\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 4 · 10/09/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5798361)\n\nEsta nota es información editorial del buscador y no forma parte de la publicación oficial. Referencias del radar con corte al 14 de septiembre de 2026, cotejadas para esta incorporación.\n","tipo_articulo":"complementario","titulo_nombre":"Información editorial de la versión","capitulo_nombre":null,"seccion_nombre":null},{"id":"3d282f0c-d8a2-5fa6-b89b-84814dcfc105","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":1,"identificador":"Preámbulo del acuerdo modificatorio","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n ACUERDO por el que se emite la modificación a la Segunda Convocatoria para la atención prioritaria de solicitudes de permisos de generación de energía eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante.\n Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Energía.\n<div> LUZ ELENA GONZÁLEZ ESCOBAR, Secretaria de Energía, con fundamento en lo dispuesto por los artículos 28, párrafo noveno, 90, párrafo primero de la Constitución Política de los Estados Unidos Mexicanos; 2, fracción I, 14, párrafo primero, 26, fracción IX y 33, fracciones I, IV, V, XXIX y XXXIII de la Ley Orgánica de la Administración Pública Federal; 4 de la Ley Federal de Procedimiento Administrativo; 2 y 10 fracción II de la Ley del Sector Eléctrico, 57 del Reglamento de la Ley de Planeación y Transición Energética, y 3 y 13 del Reglamento de la Ley del Sector Eléctrico, y</div>\n<div> CONSIDERANDO<br> </div>\n<div> Que el 11 de mayo de 2026, se publicó en el Diario Oficial de la Federación la &quot;SEGUNDA CONVOCATORIA PARA LA ATENCIÓN PRIORITARIA DE SOLICITUDES DE PERMISOS DE GENERACIÓN DE ENERGÍA ELÉCTRICA E INTERCONEXIÓN AL SISTEMA ELÉCTRICO NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE&quot;, dirigida a todas las personas solicitantes interesadas en desarrollar nuevos proyectos de generación de energía eléctrica con capacidad igual o mayor a 0.7 MW, que pretendan interconectarse al Sistema Eléctrico Nacional.</div>\n<div> Que la Segunda Convocatoria establece el mecanismo para la atención prioritaria de las solicitudes para la obtención de los permisos de generación de energía eléctrica que se requieran para asegurar el cumplimiento de los objetivos de expansión del Sistema Eléctrico Nacional, de acuerdo con los Instrumentos de Planeación del Sector Energético.</div>\n<div> Que derivado del interés manifestado por las personas participantes y con el propósito de favorecer una mayor participación en la Segunda Convocatoria, se considera oportuno modificar las fechas y plazos previstos en el calendario contenido en la Segunda Convocatoria, por lo que he tenido a bien emitir el siguiente:</div>\n<div> ACUERDO POR EL QUE SE EMITE LA MODIFICACIÓN A LA SEGUNDA CONVOCATORIA PARA LA ATENCIÓN PRIORITARIA<br> DE SOLICITUDES DE PERMISOS DE GENERACIÓN DE ENERGÍA ELÉCTRICA E INTERCONEXIÓN AL SISTEMA ELÉCTRICO<br> NACIONAL, ALINEADOS A LA PLANEACIÓN VINCULANTE<br> </div>","tipo_articulo":"preambulo","titulo_nombre":"Segunda convocatoria de generación · publicación del 26-05-2026","capitulo_nombre":null,"seccion_nombre":null},{"id":"50928d41-7a42-59d2-99bb-8c111ea0596f","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":2,"identificador":"Resolutivo PRIMERO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> PRIMERO. Se modifican las etapas 2 a 17 del calendario previsto en el numeral 7; el segundo párrafo del numeral 8.2.; el primer párrafo de los numerales 9.1 y 9.2. de la Segunda Convocatoria para la atención prioritaria de solicitudes de permisos de generación de energía eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante, para quedar en los siguientes términos:</div>\n<div> &quot;7. ...</div>\n<div> ...</div>\n<table> <tbody><tr> <td> <div> No.<br> </div> </td> <td> <div> Etapa<br> </div> </td> <td> <div> Fechas en 2026<br> </div> </td> <td> <div> Consideraciones sobre la etapa<br> </div> </td> <td> <div> Acciones que las personas<br> solicitantes deben realizar<br> </div> </td> </tr> <tr> <td> <div> 2<br> </div> </td> <td> <div> Periodo de registro de<br> manifestación de interés y<br> solicitud de estudios de<br> interconexión, a través de la<br> VUPE.<br> </div> </td> <td> <div> 13 al 29 de mayo<br> </div> </td> <td> <div> Las personas interesadas en participar en la Segunda Convocatoria deben ingresar a la VUPE para presentar su registro de manifestación de interés para participar en esta, así como para presentar la solicitud de estudios de interconexión del CENACE.</div> </td> <td> <div> Registrar su manifestación<br> de interés y solicitud de<br> estudios de interconexión del<br> CENACE, para lo cual,<br> deben completar en la VUPE<br> el Formato de Manifestación<br> de Interés y Solicitud de<br> estudios de interconexión del<br> CENACE.<br> </div> </td> </tr> <tr> <td> <div> 3<br> </div> </td> <td> <div> Prevención por parte de<br> CENACE y atención de la<br> persona solicitante<br> </div> </td> <td> <div> 01 al 04 de junio<br> </div> </td> <td> <div> En el caso de que la solicitud de estudios de interconexión no contenga los datos o no cumplan con los requisitos aplicables, el CENACE debe prevenir a la persona solicitante para que subsanen la omisión dentro del plazo previsto en este calendario.</div> <div> Si la persona interesada no remite la información que le requiere el CENACE, el CENACE le debe notificar que no resulta procedente realizar un estudio al amparo de la Segunda Convocatoria.</div> <div> En ningún caso se puede otorgar alguna prórroga para presentar la información que el CENACE le requiera.</div> </td> <td> <div> Dar atención a la prevención<br> </div> </td> </tr> <tr> <td> <div> 4<br> </div> </td> <td> <div> Periodo para que el<br> CENACE determine los<br> pagos que se le deben<br> realizar por concepto de los<br> estudios de interconexión,<br> según corresponda.<br> </div> </td> <td> <div> 05 al 08 de junio<br> </div> </td> <td> <div> Por medio de la VUPE, el CENACE comunica a las personas solicitantes alguna de las siguientes opciones:</div> <div> 1. El monto a pagar, para lo cual se le notifica a la persona solicitante la línea de captura de pago correspondiente;</div> <div> 2. Que la información presentada resulta suficiente para la revalidación de los estudios que presentó, por lo que no debe realizar un pago adicional.</div> </td> <td> <div> Presentar en tiempo y forma<br> la información que, en su<br> caso, le requiera el<br> CENACE.<br> </div> </td> </tr> <tr> <td> <div> 5<br> </div> </td> <td> <div> Periodo para el pago de los<br> estudios realizados por el<br> CENACE.<br> </div> </td> <td> <div> 09 al 15 de junio<br> </div> </td> <td> <div> Las personas solicitantes deben realizar el pago de la línea de captura enviada por el CENACE y presentar la evidencia de dicho pago en la VUPE, para los casos que resulten conducentes. Las personas que no acrediten realizar el pago correspondiente no pueden obtener un permiso de generación de energía eléctrica con base en la Segunda Convocatoria.</div> </td> <td> <div> Presentar el comprobante<br> del pago de la línea de<br> captura que le notificó el<br> CENACE a través de la<br> VUPE.<br> </div> </td> </tr> <tr> <td> <div> 6<br> </div> </td> <td> <div> Presentación de la solicitud<br> de permiso de generación de<br> energía eléctrica ante la<br> CNE.<br> </div> </td> <td> <div> 16 de junio al 15 de<br> julio<br> </div> </td> <td> <div> Se presenta en la OPE de la CNE, para lo cual la persona solicitante debe acreditar el cumplimiento de las Disposiciones de Permisos.</div> </td> <td> <div> Presentar la solicitud de<br> permiso de generación de<br> energía eléctrica a través de<br> la OPE de la CNE.<br> </div> </td> </tr> <tr> <td> <div> 7<br> </div> </td> <td> <div> Revisión de cumplimiento de<br> requisitos por parte de las<br> personas solicitantes y<br> notificación de prevenciones.<br> </div> </td> <td> <div> 16 al 20 de julio<br> </div> </td> <td> <div> La CNE debe revisar el cumplimiento de los requisitos previstos en las Disposiciones de Permisos. En caso de que identifique que hace falta información para evaluar la solicitud o que esta presenta inconsistencias respecto de lo que la persona informó a través de la VUPE, la CNE debe realizar una única prevención que se debe notificar a través de su OPE a las personas solicitantes. Concluida esta revisión y, en su caso, desahogadas las prevenciones, la CNE debe integrar la relación de solicitudes que continúan en el proceso y remitirla al CENACE para la notificación de estudios, costos de Obras de Refuerzo y costos de Obras de Interconexión.</div> </td> <td> <div> Revisar las notificaciones<br> que la CNE le realice a<br> través de su OPE.<br> </div> </td> </tr> <tr> <td> <div> 8<br> </div> </td> <td> <div> Atención de las prevenciones<br> que, en su caso, notifique la<br> CNE.<br> </div> </td> <td> <div> 21 al 24 de julio<br> </div> </td> <td> <div> Las personas solicitantes deben atender la única prevención que les realice la CNE mediante la presentación de la información y documentación que corresponda. Si la prevención es atendida en tiempo y forma y la información resulta suficiente, la CNE debe incluir la solicitud en la relación que remita al CENACE para la etapa de notificación de estudios y costos. En caso de que no se atienda la prevención o la información remitida resulte insuficiente, la CNE debe notificar el desechamiento correspondiente por medio de la OPE. En este supuesto, la notificación por parte de la CNE debe realizarse a más tardar en la fecha en que le sean notificados a la persona particular los resultados de los estudios realizados por el CENACE.</div> </td> <td> <div> Presentar la información y<br> documentación que atienda<br> la prevención a través de la<br> OPE de CNE.<br> </div> </td> </tr> <tr> <td> <div> 9<br> </div> </td> <td> <div> Notificación de costos de<br> Obras de Refuerzo y de<br> interconexión.<br> </div> </td> <td> <div> 27 de julio<br> </div> </td> <td> <div> El CENACE debe notificar, a través de la VUPE, los resultados de los estudios realizados y los costos de Obras de Refuerzo y de interconexión a las personas solicitantes que la CNE le informe, esto es, aquellas que hayan cumplido cuantitativamente con los requisitos establecidos en las Disposiciones de Permisos y, en su caso, hayan desahogado satisfactoriamente la prevención.</div> </td> <td> <div> Revisar las notificaciones<br> que se realicen a través de la<br> VUPE.<br> </div> </td> </tr> <tr> <td> <div> 10<br> </div> </td> <td> <div> Aceptación expresa del costo<br> de Obras de Interconexión y<br> Obras de Refuerzo definidas<br> por el CENACE<br> </div> </td> <td> <div> 28 de julio al 04 de<br> agosto<br> </div> </td> <td> <div> Las personas solicitantes que se encuentren en el supuesto del numeral 9 anterior, deben presentar a través de la VUPE el Formato Aceptación de Obras.</div> </td> <td> <div> Presentar en la VUPE<br> </div> </td> </tr> <tr> <td> <div> 11<br> </div> </td> <td> <div> Reevaluación de resultados<br> de Obras de Refuerzo y de<br> interconexión.<br> </div> </td> <td> <div> 05 al 11 de agosto<br> </div> </td> <td> <div> Por una sola ocasión, cuando sea necesario en términos del numeral 6.2, párrafo sexto, el CENACE debe reevaluar los resultados de estudios y el costo de Obras de Interconexión y Obras de Refuerzo, y notificar la información respectiva a las personas solicitantes correspondientes dentro de los 5 días hábiles siguientes a que se actualice dicho supuesto.</div> </td> <td> <div> Ninguna<br> </div> </td> </tr> <tr> <td> <div> 12<br> </div> </td> <td> <div> Aceptación expresa del<br> Costo de Obras de Refuerzo<br> y de interconexión<br> redefinidas, resultado de la<br> etapa anterior.<br> </div> </td> <td> <div> 12 al 13 de agosto<br> </div> </td> <td> <div> Las personas solicitantes deben presentar a través de la VUPE el Formato Aceptación de Obras mediante el cual aceptan expresa e irrevocablemente las Obras de Interconexión y Obras de Refuerzo redefinidas por el CENACE. Esta aceptación se debe presentar dentro de los 2 días hábiles siguientes a la notificación de la reevaluación realizada por el CENACE.</div> </td> <td> <div> Presentar en la VUPE el<br> Formato Aceptación de<br> Obras respecto de la<br> reevaluación notificada por el<br> CENACE.<br> </div> </td> </tr> <tr> <td> <div> 13<br> </div> </td> <td> <div> Evaluación de los estudios<br> técnicos y criterios de la<br> planeación vinculante.<br> </div> </td> <td> <div> 14 al 19 de agosto<br> </div> </td> <td> <div> La CNE debe someter ante el Grupo de Análisis Técnico la información técnica integrada resultante del desarrollo de la Segunda Convocatoria, en términos de las Disposiciones para la Planeación Vinculante.</div> </td> <td> <div> Ninguna<br> </div> </td> </tr> <tr> <td> <div> 14<br> </div> </td> <td> <div> Revisión y aprobación de<br> permisos por parte del<br> Comité Técnico de la CNE.<br> </div> </td> <td> <div> 20 al 21 de agosto<br> </div> </td> <td> <div> El Comité Técnico de la CNE, en sesión extraordinaria, debe determinar, en su caso, la aprobación de los permisos que cumplan con los requisitos establecidos en la LSE, su reglamento y demás disposiciones aplicables, incluyendo lo previsto en la Segunda Convocatoria.</div> </td> <td> <div> Ninguna<br> </div> </td> </tr> <tr> <td> <div> 15<br> </div> </td> <td> <div> Publicación de resultados de<br> la Convocatoria.<br> </div> </td> <td> <div> 24 de agosto<br> </div> </td> <td> <div> La CNE debe publicar en la VUPE y en su página de internet los resultados de la Segunda Convocatoria, esto es, las solicitudes de proyectos que fueron aprobadas para obtener un permiso de generación de energía eléctrica.</div> </td> <td> <div> Revisar la publicación<br> realizada por la CNE<br> </div> </td> </tr> <tr> <td> <div> 16<br> </div> </td> <td> <div> Notificación de los permisos<br> aprobados por parte del<br> Comité Técnico de la CNE al<br> amparo de la Convocatoria.<br> </div> </td> <td> <div> 25 de agosto<br> </div> </td> <td> <div> La CNE notifica a través de su OPE los permisos de generación de energía eléctrica que las personas solicitantes hayan obtenido al amparo de la Segunda Convocatoria.</div> </td> <td> <div> Revisar las notificaciones<br> que la CNE le realice a<br> través de su OPE.<br> </div> </td> </tr> <tr> <td> <div> 17<br> </div> </td> <td> <div> Presentación del<br> desistimiento de solicitudes<br> de otorgamiento de permisos<br> anteriores a la Convocatoria.<br> </div> </td> <td> <div> 26 al 31 de agosto<br> </div> </td> <td> <div> En su caso, las personas solicitantes que hayan obtenido los permisos correspondientes al amparo de la Segunda Convocatoria deben presentar, a través de la OPE de la CNE, el desistimiento de las solicitudes de permisos de generación de energía eléctrica que tuvieran presentadas de manera previa a la publicación de esta convocatoria.</div> </td> <td> <div> Presentar desistimiento de<br> trámites previos a través de<br> la OPE de la CNE.<br> </div> </td> </tr> </tbody></table>\n<div> ...&quot;</div>\n<div> &quot;8.2. ...</div>\n<div> ...</div>\n<div> I...</div>\n<div> II. ...</div>\n<div> La SENER y el CENACE deben entregar a la CNE la información solicitada a más tardar el 13 de agosto de 2026.</div>\n<div> ...&quot;</div>\n<div> &quot;9.1. ...</div>\n<div> El Comité Técnico de la CNE debe resolver sobre la aprobación de las solicitudes que se le sometan a consideración en la sesión extraordinaria que se celebre del 20 al 21 de agosto de 2026, conforme a lo previsto en la LCNE y las Reglas de Operación de dicho Comité, para lo cual les debe ser remitido el expediente administrativo que incluya toda la información presentada por la persona particular, así como, en su caso la proporcionada por la SENER, el CENACE y el Grupo de Análisis Técnico.&quot;</div>\n<div> &quot;9.2. ...</div>\n<div> La CNE debe emitir y notificar los títulos de permisos aprobados por el Comité Técnico de la CNE, respecto de permisos de generación de energía eléctrica, el 25 de agosto de 2026.</div>\n<div> ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Segunda convocatoria de generación · publicación del 26-05-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":null},{"id":"7c441bb7-a86e-512c-aef9-4189eb539aba","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":3,"identificador":"Resolutivo SEGUNDO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> SEGUNDO. Los plazos y referencias contenidas en la Segunda Convocatoria para la atención prioritaria de solicitudes de permisos de </div>\n<div> generación de energía eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante, deben entenderse conforme a lo previsto en la modificación a que se refiere el numeral anterior.</div>","tipo_articulo":"ordinario","titulo_nombre":"Segunda convocatoria de generación · publicación del 26-05-2026","capitulo_nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","seccion_nombre":null},{"id":"5e05f07e-3d77-58c5-b542-88b0bed9cc92","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":4,"identificador":"Transitorio ÚNICO · acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> TRANSITORIO<br> </div>\n<div> ÚNICO. El presente Acuerdo entrará en vigor el mismo día de su publicación en el Diario Oficial  de la Federación.</div>","tipo_articulo":"transitorio","titulo_nombre":"Segunda convocatoria de generación · publicación del 26-05-2026","capitulo_nombre":"Transitorios del acuerdo modificatorio","seccion_nombre":null},{"id":"5c17b4cf-c94f-5423-896d-8a601c991bf1","ley_id":"f7419b4e-49eb-5425-a439-562f25a4d581","orden":5,"identificador":"Firma del acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> Ciudad de México, a 22 de mayo de 2026.- La Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.</div>","tipo_articulo":"complementario","titulo_nombre":"Segunda convocatoria de generación · publicación del 26-05-2026","capitulo_nombre":"Documentos complementarios","seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial de la versión","orden":0},{"nivel":"capitulo","nombre":"Resolutivo PRIMERO del acuerdo modificatorio","orden":1},{"nivel":"capitulo","nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","orden":2},{"nivel":"capitulo","nombre":"Transitorios del acuerdo modificatorio","orden":3}],"fuente":{"name":"CONV-GEN-2-M1","code":"5788509","radar":"RAD-038","familia":"Segunda convocatoria de generación","modificacion":1,"url":"https://sidof.segob.gob.mx/notas/docFuente/5788509","sha256":"0cf5044b5ca7356b4469a7d5c596f7533b554819ee77f52a3eb60b34768b26b6","fecha":"26-05-2026","titulo":"Acuerdo por el que se emite la modificación a la Segunda Convocatoria para la atención prioritaria de solicitudes de permisos de generación de energía eléctrica e interconexión al Sistema Eléctrico Nacional, alineados a la planeación vinculante.","codDiario":327526,"pagina":46,"tables":1,"images":[]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='f7419b4e-49eb-5425-a439-562f25a4d581';
